// src/components/SignIn.js
import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { toast } from 'react-toastify';

const SignIn = ({ onAuth }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ email: '', password: '' });

  const handleChange = (e) => {
    setFormData({...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // simulate auth
    if (formData.email && formData.password) {
      onAuth({ name: 'User', email: formData.email });
      toast.success('Welcome back!');
      navigate('/dashboard');
    } else {
      toast.error('Please fill in all fields');
    }
  };

  return (
    <div className="d-flex justify-content-center align-items-center" style={{ minHeight: '80vh' }}>
    <div style={{minHeight: '100vh',backgroundImage: `url('/assests/bg1.png')`, backgroundSize: 'cover', backgroundPosition: 'center', display: 'flex', alignItems: 'center', justifyContent: 'center'}}></div>
      <div className="card shadow p-4" style={{ width: '100%', maxWidth: '400px', borderRadius: '12px', boxShadow: '0 6px 12px rgba(255, 140, 0, 0.1)' }}>
        <h2 className="card-title text-center mb-4">Sign In</h2>
        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label>Email</label>
            <input 
              type="email" 
              name="email" 
              className="form-control" 
              value={formData.email}
              onChange={handleChange}
              required />
          </div>
          <div className="mb-3">
            <label>Password</label>
            <input 
              type="password" 
              name="password" 
              className="form-control" 
              value={formData.password}
              onChange={handleChange}
              required />
          </div>
          <button type="submit" className="btn btn-primary w-100">Sign In</button>
        </form>
        <p className="text-center mt-3">
          Don't have an account? <Link to="/signup">Sign Up</Link>
        </p>
      </div>
    </div>
  );
};

export default SignIn;
